import { getActiveDeveloperRegistration, listDeveloperScenes, useDeveloperScene, } from "./DeveloperRegistry.js";
import { hexLine } from "./hex.js";
import { summarizeTopologyRenderFrame } from "./renderPipeline.js";
export const developerApiVersion = "0.1.0";
function activeRegistration() {
    const registration = getActiveDeveloperRegistration();
    if (!registration?.scene) {
        throw new Error("No Operational Topology scene is registered on this page.");
    }
    return registration;
}
function graphPath(fromId, toId) {
    const scene = activeRegistration().scene;
    if (fromId === toId)
        return [fromId];
    const adjacency = new Map();
    for (const relationship of scene.relationships()) {
        adjacency.set(relationship.from, [...(adjacency.get(relationship.from) ?? []), relationship.to]);
        adjacency.set(relationship.to, [...(adjacency.get(relationship.to) ?? []), relationship.from]);
    }
    const queue = [[fromId]];
    const visited = new Set([fromId]);
    while (queue.length) {
        const path = queue.shift();
        const current = path[path.length - 1];
        for (const neighbor of adjacency.get(current) ?? []) {
            if (visited.has(neighbor))
                continue;
            const nextPath = [...path, neighbor];
            if (neighbor === toId)
                return nextPath;
            visited.add(neighbor);
            queue.push(nextPath);
        }
    }
    return [];
}
export function createDeveloperAPI() {
    const inspect = (entityId) => activeRegistration().scene.inspect(entityId);
    return {
        version: developerApiVersion,
        help() {
            return {
                scene: ["list()", "use(sceneId)", "current()"],
                world: ["entities()", "relationships()", "find(query)"],
                grid: ["cells()", "cell(q, r)", "highlight(q, r)", "clear()"],
                camera: ["state()", "center()", "fit()", "focus(entityId)", "zoom(value)", "reset()"],
                graph: ["neighbors(entityId)", "path(fromId, toId)", "hexPath(fromId, toId)"],
                inspector: ["inspect(entityId)"],
                signal: ["broadcast(entityId)", "path(fromId, toId)", "stop()"],
                debug: ["layers()", "viewport()", "frame()", "performance()"],
            };
        },
        scene: {
            list: listDeveloperScenes,
            use: useDeveloperScene,
            current: () => getActiveDeveloperRegistration()?.id ?? null,
        },
        world: {
            entities: () => activeRegistration().scene.entities(),
            relationships: () => activeRegistration().scene.relationships(),
            find(query) {
                const normalized = query.trim().toLowerCase();
                return activeRegistration().scene.entities().filter((entity) => entity.id.toLowerCase().includes(normalized) ||
                    entity.label.toLowerCase().includes(normalized) ||
                    entity.subtitle?.toLowerCase().includes(normalized));
            },
        },
        grid: {
            cells: () => activeRegistration().scene.cells(),
            cell: (q, r) => activeRegistration().scene.cells().find((cell) => cell.q === q && cell.r === r) ?? null,
            highlight: (q, r) => activeRegistration().scene.highlight(q, r),
            clear: () => activeRegistration().scene.clearHighlights(),
        },
        camera: {
            state: () => activeRegistration().camera?.get() ?? null,
            center: () => activeRegistration().camera?.center(),
            fit: () => activeRegistration().camera?.fit(),
            focus: (entityId) => activeRegistration().camera?.focus(entityId) ?? false,
            zoom(value) {
                if (!Number.isFinite(value) || value <= 0) {
                    throw new TypeError("Camera zoom must be a positive finite number.");
                }
                activeRegistration().camera?.zoom(value);
            },
            reset: () => activeRegistration().camera?.reset(),
        },
        graph: {
            neighbors(entityId) {
                const relationships = activeRegistration().scene.relationships();
                const ids = relationships.flatMap((relationship) => relationship.from === entityId
                    ? [relationship.to]
                    : relationship.to === entityId
                        ? [relationship.from]
                        : []);
                const unique = new Set(ids);
                return activeRegistration().scene.entities().filter((entity) => unique.has(entity.id));
            },
            path: graphPath,
            hexPath(fromId, toId) {
                const entities = activeRegistration().scene.entities();
                const from = entities.find((entity) => entity.id === fromId);
                const to = entities.find((entity) => entity.id === toId);
                return from && to ? hexLine(from, to) : [];
            },
        },
        inspector: { inspect },
        inspect,
        signal: {
            broadcast: (entityId) => activeRegistration().scene.broadcast(entityId),
            path: (fromId, toId) => activeRegistration().scene.path(fromId, toId),
            stop: () => activeRegistration().scene.stopSignals(),
        },
        debug: {
            layers: () => activeRegistration().scene.frame().layers,
            viewport: () => activeRegistration().camera?.get() ?? null,
            frame: () => activeRegistration().scene.frame(),
            performance() {
                const frame = activeRegistration().scene.frame();
                return summarizeTopologyRenderFrame(frame);
            },
        },
    };
}
export function installDeveloperAPI() {
    if (typeof window === "undefined")
        return null;
    window.otf ??= createDeveloperAPI();
    return window.otf;
}
